  package    org . cloudbus . cloudsim . lists ;   import   java . util . List ;  import    org . cloudbus . cloudsim . Host ;   public class HostList  {   public static  <  T  extends Host > T getById  (   List  < T > hostList ,   int id )  {  for ( T host : hostList )  {  if  (   host . getId  ( ) == id )  {  return host ; } }  return null ; }   public static  <  T  extends Host >  int getNumberOfPes  (   List  < T > hostList )  {   int  numberOfPes = 0 ;  for ( T host : hostList )  {   numberOfPes +=   host . getPeList  ( ) . size  ( ) ; }  return numberOfPes ; }   public static  <  T  extends Host >  int getNumberOfFreePes  (   List  < T > hostList )  {   int  numberOfFreePes = 0 ;  for ( T host : hostList )  {   numberOfFreePes +=  PeList . getNumberOfFreePes  (  host . getPeList  ( ) ) ; }  return numberOfFreePes ; }   public static  <  T  extends Host >  int getNumberOfBusyPes  (   List  < T > hostList )  {   int  numberOfBusyPes = 0 ;  for ( T host : hostList )  {   numberOfBusyPes +=  PeList . getNumberOfBusyPes  (  host . getPeList  ( ) ) ; }  return numberOfBusyPes ; }   public static  <  T  extends Host > T getHostWithFreePe  (   List  < T > hostList )  {  return  getHostWithFreePe  ( hostList , 1 ) ; }   public static  <  T  extends Host > T getHostWithFreePe  (   List  < T > hostList ,   int pesNumber )  {  for ( T host : hostList )  {  if  (   PeList . getNumberOfFreePes  (  host . getPeList  ( ) ) >= pesNumber )  {  return host ; } }  return null ; }   public static  <  T  extends Host > boolean setPeStatus  (   List  < T > hostList ,   int status ,   int hostId ,   int peId )  {  T  host =  getById  ( hostList , hostId ) ;  if  (  host == null )  {  return false ; }  return  host . setPeStatus  ( peId , status ) ; } }